#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    int ia = *(const int *)a;
    int ib = *(const int *)b;
    return (ia > ib) - (ia < ib);
}

int main(void) {
    int n, i;
    int a[128];
    scanf("%d", &n);
    for (i = 0; i < n; i++) scanf("%d", &a[i]);
    /* TODO: 调用 qsort 对 a 的前 n 个元素排序 */
    for (i = 0; i < n; i++) printf("%d%c", a[i], i == n - 1 ? '\n' : ' ');
    return 0;
}

