int cmp(const void *a, const void *b) {
    return (*(const int *)a > *(const int *)b) - (*(const int *)a < *(const int *)b);
}

int main(void) {
    int n, target, i;
    int a[128];
    int *p;
    scanf("%d", &n);
    for (i = 0; i < n; i++) scanf("%d", &a[i]);
    scanf("%d", &target);
    /* TODO: 调用 bsearch 在 a 中查找 target，结果赋给 p */
    if (p) printf("%d\n", (int)(p - a));
    else printf("not found\n");
    return 0;
}

