problems.reference:
#include <stdio.h>
#include <string.h>

int main(void) {
    char s[256];
    int p, len;
    fgets(s, sizeof(s), stdin);
    s[strcspn(s, "\n")] = 0;
    scanf("%d", &p);
    len = (int)strlen(s);
    if (p >= 0 && p < len)
        memmove(s + p, s + p + 1, (size_t)(len - p));
    printf("%s\n", s);
    return 0;
}

