#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n, i, sum = 0;
    int *a;
    scanf("%d", &n);
    a = malloc(n * sizeof(int));
    if (a == NULL)
        return 1;
    for (i = 0; i < n; i++) {
        scanf("%d", &a[i]);
        sum += a[i];
    }
    printf("%d\n", sum);
    free(a);
    return 0;
}

