int main(void) {
    int n, m, i, *a;
    scanf("%d %d", &n, &m);
    a = malloc(n * sizeof(int));
    if (!a)
        return 1;
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    {
        int *b = realloc(a, (n + m) * sizeof(int));
        if (!b) {
            free(a);
            return 1;
        }
        a = b;
    }
    for (i = 0; i < m; i++)
        scanf("%d", &a[n + i]);
