#include <stdio.h>
void qs(int a[], int lo, int hi) {
    int i = lo, j = hi, p = a[(lo + hi) / 2], t;
    while (i <= j) {
        while (a[i] < p)
            i++;
        while (a[j] > p)
            j--;
        if (i <= j) {
            t = a[i];
            a[i] = a[j];
            a[j] = t;
            i++;
            j--;
        }
    }
    if (lo < j)
        qs(a, lo, j);
    if (i < hi)
        qs(a, i, hi);
}
