#include <stdio.h>
#define CAP 512
int main(void) {
    int n, k, i, s = 0, ans = 0, a[128];
    int psum[CAP], pcnt[CAP], used[CAP];
    if (scanf("%d", &n) != 1)
        return 0;
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    scanf("%d", &k);
    for (i = 0; i < CAP; i++)
        used[i] = 0;
    /* 插入前缀和 0 */
    {
        int h = 0;
        while (used[h])
            h = (h + 1) % CAP;
        used[h] = 1;
        psum[h] = 0;
        pcnt[h] = 1;
    }
    for (i = 0; i < n; i++) {
        s += a[i];
        {
            int target = s - k, t = (target % CAP + CAP) % CAP;
            while (used[t] && psum[t] != target)
                t = (t + 1) % CAP;
            if (used[t] && psum[t] == target)
                ans += pcnt[t];
        }
        {
            int ins = (s % CAP + CAP) % CAP;
            while (used[ins] && psum[ins] != s)
                ins = (ins + 1) % CAP;
            if (used[ins] && psum[ins] == s)
                pcnt[ins]++;
            else {
                used[ins] = 1;
                psum[ins] = s;
                pcnt[ins] = 1;
            }
        }
    }
    printf("%d\n", ans);
    return 0;
}

