#include <stdio.h>
void sift(int a[], int n, int i) {
    int largest = i, l = 2 * i + 1, r = 2 * i + 2, t;
    if (l < n && a[l] > a[largest])
        largest = l;
    if (r < n && a[r] > a[largest])
        largest = r;
    if (largest != i) {
        t = a[i];
        a[i] = a[largest];
        a[largest] = t;
        sift(a, n, largest);
    }
}
int main(void) {
    int n, i, t, a[128];
