        return 0;
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    for (i = n / 2 - 1; i >= 0; i--)
        sift(a, n, i);
    for (i = n - 1; i > 0; i--) {
        t = a[0];
        a[0] = a[i];
        a[i] = t;
        sift(a, i, 0);
