#include <stdio.h>
void swap(int *x, int *y) {
    int t = *x;
    *x = *y;
    *y = t;
}
int partition(int a[], int lo, int hi) {
    int pivot = a[hi], i = lo - 1, j;
    for (j = lo; j < hi; j++) {
        if (a[j] >= pivot) {
            i++;
            swap(&a[i], &a[j]);
        }
    }
    swap(&a[i + 1], &a[hi]);
    return i + 1;
}
int quickSelect(int a[], int lo, int hi, int k) {
    if (lo == hi)
        return a[lo];
    int p = partition(a, lo, hi);
    int rank = p - lo;
    if (rank == k)
        return a[p];
    else if (rank > k)
        return quickSelect(a, lo, p - 1, k);
    else
        return quickSelect(a, p + 1, hi, k - rank - 1);
}
int main(void) {
    int n, k, i, a[128];
    if (scanf("%d%d", &n, &k) != 2)
        return 0;
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    printf("%d\n", quickSelect(a, 0, n - 1, k - 1));
    return 0;
}

