#include <stdio.h>

static char *save = NULL;

char *my_strtok(char *s, char delim) {
    char *p;
    if (s != NULL)
        save = s;
    if (save == NULL)
        return NULL;
    p = save;
    while (*p == delim)
        p++;
    if (*p == '\0') {
        save = NULL;
        return NULL;
    }
    save = p;
    while (*save != '\0' && *save != delim)
        save++;
    if (*save != '\0') {
        *save = '\0';
        save++;
    } else
        save = NULL;
    return p;
}

