#include <stdio.h>

void quicksort(int a[], int low, int high) {
    int i, j, pivot, t;
    if (low >= high)
        return;
    pivot = a[low];
    i = low;
    j = high;
    while (i < j) {
        while (i < j && a[j] >= pivot)
            j--;
        if (i < j) {
            a[i] = a[j];
            i++;
        }
        while (i < j && a[i] <= pivot)
            i++;
        if (i < j) {
            a[j] = a[i];
            j--;
        }
    }
    a[i] = pivot;
    quicksort(a, low, i - 1);
    quicksort(a, i + 1, high);
}

int main(void) {
    int n, a[1000], i;
    scanf("%d", &n);
    for (i = 0; i < n; i++)
