#include <stdio.h>

void heap_sort(int a[], int n) {
    int i, k;
    for (i = n / 2 - 1; i >= 0; i--) {
        int j = i;
        while (1) {
            int largest = j;
            int l = 2 * j + 1, r = 2 * j + 2;
            if (l < n && a[l] > a[largest])
                largest = l;
            if (r < n && a[r] > a[largest])
                largest = r;
            if (largest == j)
                break;
            int t = a[j];
            a[j] = a[largest];
            a[largest] = t;
            j = largest;
        }
    }
    for (k = n - 1; k > 0; k--) {
        int t = a[0];
        a[0] = a[k];
        a[k] = t;
        int j = 0;
        while (1) {
            int largest = j;
            int l = 2 * j + 1, r = 2 * j + 2;
            if (l < k && a[l] > a[largest])
                largest = l;
            if (r < k && a[r] > a[largest])
                largest = r;
            if (largest == j)
                break;
            int t2 = a[j];
            a[j] = a[largest];
            a[largest] = t2;
            j = largest;
        }
    }
}

