#include <stdio.h>
#include <string.h>

long my_strtol(const char *s) {
    int i = 0, sign = 1;
    long val = 0;
    while (s[i] == ' ' || s[i] == '\t') i++;
    if (s[i] == '-' || s[i] == '+') {
        if (s[i] == '-') sign = -1;
        i++;
    }
    if (s[i] == '0' && (s[i + 1] == 'x' || s[i + 1] == 'X')) {
        i += 2;
        while (s[i] != '\0') {
            int d;
            if (s[i] >= '0' && s[i] <= '9') d = s[i] - '0';
            else if (s[i] >= 'a' && s[i] <= 'f') d = s[i] - 'a' + 10;
            else if (s[i] >= 'A' && s[i] <= 'F') d = s[i] - 'A' + 10;
            else break;
            val = val * 16 + d;
            i++;
        }
    } else if (s[i] == '0') {
        i++;
        while (s[i] >= '0' && s[i] <= '7') {
            val = val * 8 + (s[i] - '0');
            i++;
        }
    } else {
        while (s[i] >= '0' && s[i] <= '9') {
            val = val * 10 + (s[i] - '0');
            i++;
        }
    }
    return sign * val;
}

int main(void) {
    char buf[64];
    fgets(buf, sizeof(buf), stdin);
    buf[strcspn(buf, "\n")] = 0;
    printf("%ld\n", my_strtol(buf));
    return 0;
}

