#include <stdio.h>

int cmp(const void *a, const void *b) {
    return *(const int *)a - *(const int *)b;
}

int *my_bsearch(int *base, int n, int key, int (*cmp)(const void *, const void *)) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        int r = cmp(&key, &base[mid]);
        if (r == 0) return &base[mid];
        else if (r < 0) hi = mid - 1;
        else lo = mid + 1;
    }
    return NULL;
}

int main(void) {
    int n, key, a[1000], i;
    scanf("%d %d", &n, &key);
    for (i = 0; i < n; i++) scanf("%d", &a[i]);
    int *p = my_bsearch(a, n, key, cmp);
    if (p == NULL) printf("-1\n");
    else printf("%d\n", (int)(p - a));
    return 0;
}

